DROP TABLE IF EXISTS timer;
CREATE TABLE timer (task_name TEXT, note TEXT, ts_msec REAL);
INSERT INTO timer VALUES('file', 'the start', unixepoch('now', 'subsec'));

.print === longSqlStringReturn table with 2 columns ===

DROP TABLE IF EXISTS test_table;
CREATE TABLE test_table (id INTEGER, myField_1 TEXT);
WITH RECURSIVE person(x) AS (
    SELECT 1 UNION ALL SELECT x+1 FROM person WHERE x < 10
)
INSERT INTO test_table (id, myField_1)
SELECT x, hex(randomblob(50)) FROM person;

UPDATE test_table SET myField_1 = NULL WHERE id <= 5;

SELECT * FROM test_table;

